bool gd32h77x_tuya_reserved_test_page_get(uint32_t *address, uint32_t *size)
{
    if (address == NULL || size == NULL) {
        return false;
    }
#if defined(GD32H77X_LAYOUT_TUYA_KV_PROTECT_END)
    const uint32_t test_address = GD32H77X_LAYOUT_TUYA_KV_PROTECT_END;
    const uint32_t test_size = UINT32_C(0x00001000);
    if (test_address == UINT32_C(0x08977000) &&
        GD32H77X_LAYOUT_TUYA_END == UINT32_C(0x08980000) &&
        test_address >= GD32H77X_LAYOUT_TUYA_KV_PROTECT_BASE +
                            GD32H77X_LAYOUT_TUYA_KV_PROTECT_SIZE &&
        test_size <= GD32H77X_LAYOUT_TUYA_END - test_address) {
        *address = test_address;
        *size = test_size;
        return true;
    }
#endif
    return false;
}

static OPERATE_RET gd32h77x_flash_access_preflight(uint32_t address, uint32_t size,
                                                    gd32h77x_flash_op_t operation)
{
    const gd32h77x_flash_route_status_t status =
        gd32h77x_flash_preflight(address, size, operation);
    if (status == GD32H77X_FLASH_ROUTE_INVALID) {
        return OPRT_INVALID_PARM;
    }
    if (!gd32h77x_flash_range_valid(GD32H77X_LAYOUT_PART_TUYA, address, size, operation)) {
        return OPRT_NOT_SUPPORTED;
    }
    if (status == GD32H77X_FLASH_ROUTE_UNSUPPORTED) {
        return OPRT_NOT_SUPPORTED;
    }
    return OPRT_OK;
}

static uint32_t gd32h77x_flash_device_index(const gd32h77x_layout_device_t *device)
{
    return (uint32_t)(device - gd32h77x_layout_devices);
}

static bool gd32h77x_flash_read_chunk(const gd32h77x_flash_route_chunk_t *chunk,
                                      void *context)
{
    uint8_t **destination = context;
    int result;
    if (strcmp(chunk->device->region, "NOR") == 0) {
        result = gd32h77x_nor_read(gd32h77x_flash_device_index(chunk->device),
                                   chunk->device_offset, *destination, chunk->size);
    } else if (strcmp(chunk->device->region, "ECNVM") == 0) {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        result = gd32h77x_ecnvm_read(address, *destination, chunk->size) == GD32H77X_STATUS_OK ? 0 : -1;
    } else {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        result = gd32h77x_cnvm_read(address, *destination, chunk->size) == GD32H77X_STATUS_OK ? 0 : -1;
    }
    if (result != 0) {
        return false;
    }
    *destination += chunk->size;
    return true;
}

typedef struct {
    const uint8_t *source;
    OPERATE_RET result;
} gd32h77x_flash_write_context_t;

static bool gd32h77x_flash_write_chunk(const gd32h77x_flash_route_chunk_t *chunk,
                                       void *context)
{
    gd32h77x_flash_write_context_t *write_context = context;
    if (strcmp(chunk->device->region, "NOR") == 0) {
        write_context->result =
            gd32h77x_nor_program(gd32h77x_flash_device_index(chunk->device),
                                 chunk->device_offset, write_context->source,
                                 chunk->size) == 0 ? OPRT_OK : OPRT_COM_ERROR;
    } else if (strcmp(chunk->device->region, "ECNVM") == 0) {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        write_context->result = gd32h77x_native_status_to_oprt(
            gd32h77x_ecnvm_program(address, write_context->source, chunk->size));
    } else {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        write_context->result = gd32h77x_native_status_to_oprt(
            gd32h77x_cnvm_program(address, write_context->source, chunk->size));
    }
    if (write_context->result != OPRT_OK) {
        return false;
    }
    write_context->source += chunk->size;
    return true;
}

typedef struct {
    OPERATE_RET result;
} gd32h77x_flash_erase_context_t;

static bool gd32h77x_flash_erase_chunk(const gd32h77x_flash_route_chunk_t *chunk,
                                       void *context)
{
    gd32h77x_flash_erase_context_t *erase_context = context;
    if (strcmp(chunk->device->region, "NOR") == 0) {
        const uint32_t device_index = gd32h77x_flash_device_index(chunk->device);
        for (uint32_t offset = 0U; offset < chunk->size; offset += 4096U) {
            if (gd32h77x_nor_erase_4k(device_index, chunk->device_offset + offset) != 0) {
                erase_context->result = OPRT_COM_ERROR;
                return false;
            }
        }
        erase_context->result = OPRT_OK;
    } else if (strcmp(chunk->device->region, "ECNVM") == 0) {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        erase_context->result = gd32h77x_native_status_to_oprt(
            gd32h77x_ecnvm_erase(address, chunk->size));
        if (erase_context->result != OPRT_OK) {
            gd32h77x_flash_report_failure("ECNVM erase", address, chunk->size, erase_context->result);
        }
    } else {
        const uint32_t address = chunk->device->cpu_base + chunk->device_offset;
        erase_context->result = gd32h77x_native_status_to_oprt(
            gd32h77x_cnvm_erase(address, chunk->size));
    }
    return erase_context->result == OPRT_OK;
}
