/**
 * @brief read flash
 *
 * @param[in] addr: flash address
 * @param[out] dst: pointer of buffer
 * @param[in] size: size of buffer
 *
 * @note This API is used for reading flash.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_flash_read(uint32_t addr, uint8_t *dst, uint32_t size)
{
    // --- BEGIN: user implements ---

    if (size != 0U && dst == NULL) {
        return OPRT_INVALID_PARM;
    }
    const OPERATE_RET preflight =
        gd32h77x_flash_access_preflight(addr, size, GD32H77X_FLASH_OP_READ);
    if (preflight != OPRT_OK) {
        return preflight;
    }
    if (size == 0U) {
        return OPRT_OK;
    }

    if (!gd32h77x_flash_route(addr, size, GD32H77X_FLASH_OP_READ,
                              gd32h77x_flash_read_chunk, &dst)) {
        /* Routing was preflighted above; reaching this is a layout inconsistency. */
        return OPRT_NOT_SUPPORTED;
    }
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief write flash
 *
 * @param[in] addr: flash address
 * @param[in] src: pointer of buffer
 * @param[in] size: size of buffer
 *
 * @note This API is used for writing flash.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_flash_write(uint32_t addr, const uint8_t *src, uint32_t size)
{
    // --- BEGIN: user implements ---

    if (size != 0U && src == NULL) {
        return OPRT_INVALID_PARM;
    }
    const OPERATE_RET preflight =
        gd32h77x_flash_access_preflight(addr, size, GD32H77X_FLASH_OP_WRITE);
    if (preflight != OPRT_OK) {
        return preflight;
    }
    if (size == 0U) {
        return OPRT_OK;
    }

    gd32h77x_flash_write_context_t context = {
        .source = src,
        .result = OPRT_OK,
    };
    if (!gd32h77x_flash_route(addr, size, GD32H77X_FLASH_OP_WRITE,
                              gd32h77x_flash_write_chunk, &context)) {
        return context.result == OPRT_OK ? OPRT_NOT_SUPPORTED : context.result;
    }
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief erase flash
 *
 * @param[in] addr: flash address
 * @param[in] size: size of flash block
 *
 * @note This API is used for erasing flash.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_flash_erase(uint32_t addr, uint32_t size)
{
    // --- BEGIN: user implements ---

    const OPERATE_RET preflight =
        gd32h77x_flash_access_preflight(addr, size, GD32H77X_FLASH_OP_ERASE);
    if (preflight != OPRT_OK) {
        gd32h77x_flash_report_failure("erase preflight", addr, size, preflight);
        return preflight;
    }

    gd32h77x_flash_erase_context_t context = {.result = OPRT_OK};
    if (!gd32h77x_flash_route(addr, size, GD32H77X_FLASH_OP_ERASE,
                              gd32h77x_flash_erase_chunk, &context)) {
        return context.result == OPRT_OK ? OPRT_NOT_SUPPORTED : context.result;
    }
    return OPRT_OK;
    // --- END: user implements ---
}

